using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class TimelineEditorOperations
{
    private readonly Expression _stateEqual=StateEquality();private static Expression StateEquality(){var result=new Expression();result.Parse("a == b",new[]{"a","b"});return result;}
    public void connect_timing_input(Control owner,SpinBox input,string kind){var model=Model(owner);string Primary()=>model.Get("selected_id").AsString();input.Connect("interaction_started",Callable.From(()=>{owner.Set("_timing_drag_kind",kind);owner.Set("_timing_drag_original",capture_clip_states(owner));Hint(owner,input,"Drag to change "+kind+" • Esc cancels");}));input.Connect("preview_changed",Callable.From<double>(value=>{if(owner.Get("_timing_drag_kind").AsString()!=kind)return;_timeline.preview_clip_states(model,timing_states(owner,value,kind,owner.Get("_timing_drag_original").AsGodotDictionary()),Primary());}));input.Connect("drag_committed",Callable.From<double>(_=>{if(owner.Get("_timing_drag_kind").AsString()!=kind)return;var final=capture_clip_states(owner);var before=owner.Get("_timing_drag_original").AsGodotDictionary();if(!_stateEqual.Execute(new GArray{final,before}).AsBool())_timeline.commit_clip_state_preview(model,before,final,"Change Actor "+kind.Capitalize(),Primary());owner.Set("_timing_drag_kind","");owner.Set("_timing_drag_original",new Settings());Hint(owner,input,"");refresh(owner);}));input.Connect("drag_cancelled",Callable.From(()=>{var before=owner.Get("_timing_drag_original").AsGodotDictionary();if(owner.Get("_timing_drag_kind").AsString()==kind&&before.Count>0)_timeline.preview_clip_states(model,before,Primary());owner.Set("_timing_drag_kind","");owner.Set("_timing_drag_original",new Settings());Hint(owner,input,"");}));input.Connect("interaction_ended",Callable.From(()=>Hint(owner,input,"")));input.ValueChanged+=value=>{if(owner.Get("_timing_drag_kind").AsString().Length>0)return;_timeline.commit_clip_states(model,timing_states(owner,value,kind,capture_clip_states(owner)),"Change Actor "+kind.Capitalize(),Primary());refresh(owner);};}
    public void focus_selected_actor(Control owner){var actor=_timeline.selected_actor(Model(owner));if(actor==null)return;_timelineCanvas.cancel_drag(Canvas(owner));_timeline.focus_actor(Model(owner),actor.Get("id").AsString());Canvas(owner).GrabFocus();}
    public void update_breadcrumbs(Control owner){var row=owner.Get("breadcrumb_row").As<HBoxContainer>();if(row==null)return;var model=Model(owner);var section=_timeline.section_for_id(model,model.Get("selected_section_id").AsString());if(section==null)return;var path=_timeline.focus_path(model);string signature=section.Get("id").AsString()+"|"+section.Get("display_name").AsString();foreach(var value in path){var actor=value.As<Resource>();signature+="|"+actor.Get("id").AsString()+"|"+actor.Get("display_name").AsString();}if(signature==owner.Get("_breadcrumb_signature").AsString())return;owner.Set("_breadcrumb_signature",signature);foreach(var child in row.GetChildren()){row.RemoveChild(child);child.QueueFree();}var root=MakeButton(row,section.Get("display_name").AsString(),()=>{_timelineCanvas.cancel_drag(Canvas(owner));_timeline.leave_actor_focus(model);Canvas(owner).GrabFocus();});root.TooltipText="Return to entire section  •  Alt+Home";foreach(var value in path){var actor=value.As<Resource>();row.AddChild(new Label{Text=" › ",Modulate=new Color("75889b")});string id=actor.Get("id").AsString();var button=MakeButton(row,actor.Get("display_name").AsString(),()=>{_timelineCanvas.cancel_drag(Canvas(owner));_timeline.focus_actor(model,id);Canvas(owner).GrabFocus();});button.TooltipText="View this actor and its descendants";if(id==model.Get("focused_actor_id").AsString())button.AddThemeStyleboxOverride("normal",box(new Color("245b5b"),new Color("72cfb8")));}}
    public void confirm_delete_section(Control owner,string id){var model=Model(owner);var section=_timeline.section_for_id(model,id);if(section==null)return;int count=Actors(owner).Count(value=>value.As<Resource>().Get("section_id").AsString()==id);if(count==0){_timelineCanvas.cancel_drag(Canvas(owner));_timeline.delete_section(model,id);return;}var dialog=new ConfirmationDialog{Title="Delete Section",DialogText=$"Delete \"{section.Get("display_name").AsString()}\" and its {count} actor(s)?\nYou can undo this action.",OkButtonText="Delete Section"};if(model.Get("sections").AsGodotArray().Count==1)dialog.DialogText+="\nA new empty section will replace the last section.";dialog.AddThemeStyleboxOverride("panel",box(new Color("202a37"),new Color("34465a")));owner.AddChild(dialog);dialog.Confirmed+=()=>{_timelineCanvas.cancel_drag(Canvas(owner));_timeline.delete_section(model,id);dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(440,170));}
    public void undo(Control owner){_timelineCanvas.cancel_drag(Canvas(owner));_timeline.undo(Model(owner));}public void redo(Control owner){_timelineCanvas.cancel_drag(Canvas(owner));_timeline.redo(Model(owner));}
    public void flush_ui_state_save(Control owner){var project=owner.Get("_ui_state_save_project").As<Resource>();if(project!=null&&project.ResourcePath.Length>0)GD.Load<GDScript>("res://scripts/Globals/file_operations.gd").Call("save_resource",project);owner.Set("_ui_state_save_project",default(Variant));}
    public void schedule_ui_state_save(Control owner){var project=StaticData.get_loaded_project();if(project==null||project.ResourcePath.Length==0)return;var previous=owner.Get("_ui_state_save_project").As<Resource>();if(previous!=null&&previous!=project)flush_ui_state_save(owner);owner.Set("_ui_state_save_project",project);var timer=owner.Get("_ui_state_save_timer").As<Timer>();if(!GodotObject.IsInstanceValid(timer)){timer=new Timer{OneShot=true};owner.Set("_ui_state_save_timer",timer);owner.AddChild(timer);timer.Connect("timeout",new Callable(owner,"_flush_ui_state_save"));}timer!.Start(.35);}
    public void input(Control owner,InputEvent input){if(input is InputEventMouseButton mouse&&mouse.Pressed&&owner.GetGlobalRect().HasPoint(mouse.Position))FocusableKeyInput.current_focused_instance = null;}
    public void unhandled_key_input(Control owner,InputEvent input){if(input is not InputEventKey key||!key.Pressed||key.Echo)return;var legacy=FocusableKeyInput.current_focused_instance;if(GodotObject.IsInstanceValid(legacy))return;var focused=owner.GetViewport().GuiGetFocusOwner();var inspector=owner.Get("inspector").As<Control>();bool owns=focused!=null&&(owner.IsAncestorOf(focused)||GodotObject.IsInstanceValid(inspector)&&inspector!.IsAncestorOf(focused));if(!owns||focused is LineEdit or TextEdit)return;handle_actor_shortcut(owner,key,focused==Canvas(owner));}
    public bool handle_actor_shortcut(Control owner,InputEventKey key,bool selection){if(!key.Pressed||key.Echo)return false;var model=Model(owner);bool selected=model.Get("selected_ids").AsGodotArray().Count>0,focused=model.Get("focused_actor_id").AsString().Length>0;var split=owner.Get("split_button").As<Button>();if(key.IsActionPressed("redo"))redo(owner);else if(key.IsActionPressed("undo"))undo(owner);else if(key.Keycode==Key.Space)toggle_playback(owner);else if(key.Keycode==Key.R&&!key.CtrlPressed)owner.Call("toggle_recording");else if(key.Keycode==Key.B&&!key.CtrlPressed)split.ButtonPressed=!split.ButtonPressed;else if(key.Keycode==Key.V&&!key.CtrlPressed)split.ButtonPressed=false;else if(key.Keycode==Key.A&&key.CtrlPressed&&selection)_timeline.select_all(model);else if(key.Keycode==Key.A&&key.ShiftPressed&&selection)owner.Get("actor_picker").As<PopupPanel>().Call("open",model.Get("selected_layer"),Time(owner));else if(key.Keycode==Key.Left&&key.AltPressed&&focused){_timelineCanvas.cancel_drag(Canvas(owner));_timeline.focus_parent(model);}else if(key.Keycode==Key.Home&&key.AltPressed&&focused){_timelineCanvas.cancel_drag(Canvas(owner));_timeline.leave_actor_focus(model);}else if(key.Keycode==Key.F&&!key.CtrlPressed&&!key.AltPressed&&selected)focus_selected_actor(owner);else if(key.Keycode==Key.D&&key.CtrlPressed&&selected)duplicate_selected(owner);else if(key.Keycode==Key.C&&key.CtrlPressed&&selected)copy_selected(owner);else if(key.Keycode==Key.V&&key.CtrlPressed&&owner.Get("_actor_clipboard").AsGodotArray().Count>0)paste_copied(owner,false,Time(owner),model.Get("selected_layer").AsInt32());else if(key.Keycode==Key.P&&key.ShiftPressed)unparent_selected(owner);else if(key.Keycode==Key.P&&model.Get("selected_ids").AsGodotArray().Count>1)parent_selected(owner);else if(key.Keycode is Key.Delete or Key.Backspace||key.IsActionPressed("delete"))delete_selected(owner);else return false;owner.GetViewport().SetInputAsHandled();return true;}
}
